mapper.select:

WHERE c.status = 'ISSUED' AND c.issued_at >= #{since}
  AND NOT EXISTS (SELECT 1 FROM tb_nft_issuances n
                   WHERE n.target_type = 'CREDENTIAL' AND n.target_id = c.id)
ORDER BY c.issued_at, c.id
LIMIT #{limit}


WHERE b.status = 'ISSUED' AND b.issued_at >= #{since}
  AND NOT EXISTS (SELECT 1 FROM tb_nft_issuances n
                   WHERE n.target_type = 'BADGE' AND n.target_id = b.id)
ORDER BY b.issued_at, b.id
LIMIT #{limit}
